#include "bfs.h"
#include "queue.h"
#include <stdlib.h>
#include <string.h>
/* O(V+E+T*V), where T is number of trace steps due to snapshots */ int bfs_run(const Graph*g,int source,int depth,BFSResult*r){if(!g||!r||source<0||(size_t)source>=g->n)return 0;memset(r,0,sizeof(*r));size_t n=g->n;r->dist=malloc(n*sizeof(int));r->parent=malloc(n*sizeof(int));if(!r->dist||!r->parent){bfs_free(r);return 0;}for(size_t i=0;i<n;i++)r->dist[i]=r->parent[i]=-1;Queue q;if(!queue_init(&q,n)){bfs_free(r);return 0;}r->dist[source]=0;queue_push(&q,source);while(q.len){int v;queue_pop(&q,&v);BFSStep s={0};s.current=v;s.queue_len=(int)q.len;s.queue=malloc((q.len?q.len:1)*sizeof(int));s.visited=malloc(n*sizeof(int));if(!s.queue||!s.visited){free(s.queue);free(s.visited);queue_free(&q);bfs_free(r);return 0;}for(size_t i=0;i<q.len;i++)s.queue[i]=q.data[(q.head+i)%q.cap];for(size_t i=0;i<n;i++)if(r->dist[i]>=0)s.visited[s.visited_len++]=(int)i;BFSStep*t=realloc(r->trace,(r->trace_len+1)*sizeof(*t));if(!t){free(s.queue);free(s.visited);queue_free(&q);bfs_free(r);return 0;}r->trace=t;r->trace[r->trace_len++]=s;if(depth>=0&&r->dist[v]>=depth)continue;for(size_t i=0;i<g->adj[v].len;i++){int w=g->adj[v].items[i];if(r->dist[w]<0){r->dist[w]=r->dist[v]+1;r->parent[w]=v;if(!queue_push(&q,w)){queue_free(&q);bfs_free(r);return 0;}}}}queue_free(&q);return 1;}
/* O(T*V) */ void bfs_free(BFSResult*r){if(!r)return;free(r->dist);free(r->parent);for(int i=0;i<r->trace_len;i++){free(r->trace[i].queue);free(r->trace[i].visited);}free(r->trace);memset(r,0,sizeof(*r));}
